18	public final class CrashUtils {
19	
20	    private static final String FILE_SEP = System.getProperty("file.separator");
21	
22	    private static final UncaughtExceptionHandler DEFAULT_UNCAUGHT_EXCEPTION_HANDLER =
23	        Thread.getDefaultUncaughtExceptionHandler();
24	
