46	     * Initialization
47	     *
48	     * @param crashDirPath The directory's path of saving crash information.
49	     */
50	    public static void init(final String crashDirPath) {
51	        init(crashDirPath, null);
52	    }
53	
54	    /**
55	     * Initialization
56	     *
57	     * @param onCrashListener The crash listener.
58	     */
59	    public static void init(final OnCrashListener onCrashListener) {
60	        init("", onCrashListener);
61	    }
62	
63	    /**
64	     * Initialization
65	     *
66	     * @param crashDir The directory of saving crash information.
67	     * @param onCrashListener The crash listener.
68	     */
69	    public static void init(@NonNull final File crashDir, final OnCrashListener onCrashListener) {
70	        init(crashDir.getAbsolutePath(), onCrashListener);
71	    }
72	
73	    /**
74	     * Initialization
75	     *
76	     * @param crashDirPath The directory's path of saving crash information.
77	     * @param onCrashListener The crash listener.
78	     */
79	    public static void init(final String crashDirPath, final OnCrashListener onCrashListener) {
80	        String dirPath;
81	        if (UtilsBridge.isSpace(crashDirPath)) {
82	            if (UtilsBridge.isSDCardEnableByEnvironment()
83	                && Utils.getApp().getExternalFilesDir(null) != null) {
84	                dirPath = Utils.getApp().getExternalFilesDir(null) + FILE_SEP + "crash" + FILE_SEP;
85	            } else {
86	                dirPath = Utils.getApp().getFilesDir() + FILE_SEP + "crash" + FILE_SEP;
87	            }
88	        } else {
89	            dirPath = crashDirPath.endsWith(FILE_SEP) ? crashDirPath : crashDirPath + FILE_SEP;
90	        }
91	        Thread.setDefaultUncaughtExceptionHandler(
92	            getUncaughtExceptionHandler(dirPath, onCrashListener));
93	    }
94	
95	    private static UncaughtExceptionHandler getUncaughtExceptionHandler(final String dirPath,
96	                                                                        final OnCrashListener onCrashListener) {
97	        return new UncaughtExceptionHandler() {
98	            @Override
99	            public void uncaughtException(@NonNull final Thread t, @NonNull final Throwable e) {
100	                final String time = new SimpleDateFormat("yyyy_MM_dd-HH_mm_ss").format(new Date());
101	                CrashInfo info = new CrashInfo(time, e);
102	                final String crashFile = dirPath + time + ".txt";
103	                UtilsBridge.writeFileFromString(crashFile, info.toString(), true);
104	
105	                if (DEFAULT_UNCAUGHT_EXCEPTION_HANDLER != null) {
106	                    DEFAULT_UNCAUGHT_EXCEPTION_HANDLER.uncaughtException(t, e);
107	                }
108	                if (onCrashListener != null) {
109	                    onCrashListener.onCrash(info);
110	                }
111	            }
112	        };
113	    }
114	
115	    ///////////////////////////////////////////////////////////////////////////
116	    // interface
117	    ///////////////////////////////////////////////////////////////////////////
118	
119	    public interface OnCrashListener {
120	        void onCrash(CrashInfo crashInfo);
121	    }
122	
123	    public static final class CrashInfo {
124	        private UtilsBridge.FileHead mFileHeadProvider;
125	        private Throwable mThrowable;
126	
127	        private CrashInfo(String time, Throwable throwable) {
128	            mThrowable = throwable;
129	            mFileHeadProvider = new UtilsBridge.FileHead("Crash");
130	            mFileHeadProvider.addFirst("Time Of Crash", time);
131	        }
132	
133	        public final void addExtraHead(Map<String, String> extraHead) {
134	            mFileHeadProvider.append(extraHead);
135	        }
136	
137	        public final void addExtraHead(String key, String value) {
138	            mFileHeadProvider.append(key, value);
139	        }
140	
141	        public final Throwable getThrowable() {
142	            return mThrowable;
143	        }
144	
145	        @Override
146	        public String toString() {
147	            return mFileHeadProvider.toString() + UtilsBridge.getFullStackTrace(mThrowable);
148	        }
149	    }
150	}
