152	    /**
153	     * Returns a {@link Collection} containing the union
154	     * of the given {@link Collection}s.
155	     * <p>
156	     * The cardinality of each element in the returned {@link Collection}
157	     * will be equal to the maximum of the cardinality of that element
158	     * in the two given {@link Collection}s.
159	     *
160	     * @param a the first collection
161	     * @param b the second collection
162	     * @return the union of the two collections
163	     * @see Collection#addAll
164	     */
165	    public static Collection union(final Collection a, final Collection b) {
166	        if (a == null && b == null) return new ArrayList();
167	        if (a == null) return new ArrayList<Object>(b);
168	        if (b == null) return new ArrayList<Object>(a);
169	        ArrayList<Object> list = new ArrayList<>();
170	        Map<Object, Integer> mapA = getCardinalityMap(a);
171	        Map<Object, Integer> mapB = getCardinalityMap(b);
172	        Set<Object> elts = new HashSet<Object>(a);
173	        elts.addAll(b);
174	        for (Object obj : elts) {
175	            for (int i = 0, m = Math.max(getFreq(obj, mapA), getFreq(obj, mapB)); i < m; i++) {
176	                list.add(obj);
177	            }
178	        }
179	        return list;
180	    }
