182	    /**
183	     * Returns a {@link Collection} containing the intersection
184	     * of the given {@link Collection}s.
185	     * <p>
186	     * The cardinality of each element in the returned {@link Collection}
187	     * will be equal to the minimum of the cardinality of that element
188	     * in the two given {@link Collection}s.
189	     *
190	     * @param a the first collection
191	     * @param b the second collection
192	     * @return the intersection of the two collections
193	     * @see Collection#retainAll
194	     */
195	    public static Collection intersection(final Collection a, final Collection b) {
196	        if (a == null || b == null) return new ArrayList();
197	        ArrayList<Object> list = new ArrayList<>();
